import re

def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    total = 0
    pattern = r'(\d+)([hms])'
    pos = 0
    for match in re.finditer(pattern, s):
        if match.start() != pos:
            raise ValueError(f"Invalid duration string: {s!r}")
        num, unit = match.groups()
        n = int(num)
        if unit == 'h':
            total += n * 3600
        elif unit == 'm':
            total += n * 60
        elif unit == 's':
            total += n
        pos = match.end()
    if pos != len(s):
        raise ValueError(f"Invalid duration string: {s!r}")
    return total
